lcb_code_gen_lite.doc_to_target:
def build_reference(doc: Dict[str, Any]) -> str:
    meta = json.loads(doc["metadata"])
    function_name = meta.get("func_name", "")
    starter_code = doc.get("starter_code", "")

    if not starter_code:
        return json.dumps(
            {
                "mode": "stdin",
                "public_test_cases": json.loads(doc["public_test_cases"]),
                "func_name": function_name,
            }
        )

    public_tests = json.loads(doc["public_test_cases"])
    assert_lines: List[str] = []
    for case in public_tests:
        inputs = [json.loads(line) for line in case["input"].split("\n")]
        arglist = ", ".join(repr(v) for v in inputs)
        out_val = json.loads(case["output"])
        if "class Solution" in starter_code:
            assert_lines.append(
                f"assert Solution().{function_name}({arglist}) == {repr(out_val)}"
            )
        else:
            assert_lines.append(f"assert {function_name}({arglist}) == {repr(out_val)}")

    return json.dumps({"mode": "func", "asserts": "\n".join(assert_lines)})

metric_list.metric:
def pass_at_1(
    references: Union[str, List[str]],
    predictions: Union[str, List[List[str]]],
) -> float:
    if isinstance(predictions, str):
        predictions = [[predictions]]
    if not predictions or not predictions[0]:
        return 0.0

    code = predictions[0][0]
    ref_obj = json.loads(references[0])
    mode = ref_obj.get("mode")
    if mode == "func":
        code = IMPORT_STRING + "\n" + code
        return pass_at_k.compute(
            references=[ref_obj["asserts"]],
            predictions=[[code]],
            k=[1],
        )[0]["pass@1"]
    elif mode == "stdin":
        statuses = run_stdin_cases_sandboxed(
            code, ref_obj["public_test_cases"], timeout=6
        )
        ok = all(s == "passed" for s in statuses)
        return 1.0 if ok else 0.0
    raise ValueError(f"Unknown mode: {mode}")
